function section(profile, y) {
  let i = 0;
  while (i < profile.length - 2 && y > profile[i + 1][0]) i++;
  const a = profile[i];
  const b = profile[i + 1];
  const before = profile[Math.max(0, i - 1)];
  const after = profile[Math.min(i + 2, profile.length - 1)];
  const span = b[0] - a[0];
  const t = clamp((y - a[0]) / span, 0, 1);
  const t2 = t * t;
  const t3 = t2 * t;

  return [1, 2, 3, 4].map(k => {
    const da = (b[k] - before[k]) * span / (b[0] - before[0]);
    const db = (after[k] - a[k]) * span / (after[0] - a[0]);
    return (2 * t3 - 3 * t2 + 1) * a[k]
      + (t3 - 2 * t2 + t) * da
      + (-2 * t3 + 3 * t2) * b[k]
      + (t3 - t2) * db;
  });
